#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (1LL << 60);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<ll>> A(N, vector<ll>(N));
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) cin >> A[i][j];
    }

    // Key observation:
    //
    // Original edges i -> i+1 have weight 0 and cannot be deleted.
    // Added edges:
    // - i -> j, i < j : weight -1
    // - i -> j, i > j : weight +1
    //
    // Any negative cycle must contain at least one backward (+1) edge,
    // because original / forward added edges only move to larger indices.
    //
    // If there is a backward edge j -> i (j > i), then together with any
    // remaining forward added edge x -> y inside interval [i, j] with x < y,
    // we get a negative cycle:
    // j -> i (+1), path i -> x by 0-edges, x -> y (-1), path y -> j by 0-edges
    // total = 0.
    // Actually this is not negative; the true dangerous structure is having
    // two forward added edges in the interval with one backward edge, etc.
    //
    // A cleaner characterization via difference constraints:
    // To avoid negative cycles, there must exist potentials p[v] such that
    // for every remaining edge u->v with weight w: p[v] <= p[u] + w.
    //
    // Original edges i->i+1 (0): p[i+1] <= p[i], so p is nonincreasing.
    // Forward edge i<j (-1): p[j] <= p[i] - 1, i.e. strict decrease.
    // Backward edge i>j (+1): p[j] <= p[i] + 1, automatically true if p is
    // nonincreasing and integer with step differences in {0,1}.
    //
    // Thus only forward edges matter: we need assign nonincreasing potentials,
    // and keeping edge i<j means p[j] <= p[i]-1. Since original edges only
    // allow total drop between i and j to be at most j-i, this is always possible.
    // The problem becomes selecting which forward edges to KEEP so that there
    // exists a nonincreasing sequence where every kept forward edge forces
    // at least one drop across interval [i, j).
    //
    // Let x_k = p[k] - p[k+1] for k=0..N-2. Then x_k >= 0.
    // Since only relative values matter and constraints are "at least 1",
    // we can take x_k in {0,1}. A kept forward edge i->j requires
    // sum_{k=i}^{j-1} x_k >= 1, i.e. at least one chosen cut in [i, j-1].
    //
    // Therefore, if S is the set of positions k where x_k=1, then a forward
    // edge i->j can be kept iff interval [i, j-1] intersects S.
    // So a forward edge must be deleted iff there is no chosen cut between i and j.
    // Backward edges never need deletion.
    //
    // Choose cuts S to minimize total deletion cost of forward edges whose
    // interval contains no cut.
    //
    // DP on last chosen cut:
    // dp[t] = minimum cost for prefix up to vertex t, where t is a chosen cut position
    // in terms of partition points. More conveniently, partition vertices into blocks
    // separated by cuts. Any forward edge entirely inside one block must be deleted.
    //
    // Let blocks be [l..r]. Cost of a block = sum of A[i][j] over l <= i < j <= r.
    // Then answer = min partition of [0..N-1] into contiguous blocks of sum block costs.
    //
    // Standard interval DP:
    // f[r+1] = min over l<=r+1 of f[l] + cost(l, r), where block is vertices l..r.
    // Also single vertex block cost = 0.

    vector<vector<ll>> pref(N + 1, vector<ll>(N + 1, 0));
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            ll val = (i < j ? A[i][j] : 0);
            pref[i + 1][j + 1] = pref[i + 1][j] + pref[i][j + 1] - pref[i][j] + val;
        }
    }

    auto blockCost = [&](int l, int r) -> ll {
        // sum of A[i][j] for l <= i < j <= r
        return pref[r + 1][r + 1] - pref[l][r + 1] - pref[r + 1][l] + pref[l][l];
    };

    vector<ll> dp(N + 1, INF);
    dp[0] = 0;
    for (int r = 0; r < N; ++r) {
        for (int l = 0; l <= r; ++l) {
            dp[r + 1] = min(dp[r + 1], dp[l] + blockCost(l, r));
        }
    }

    cout << dp[N] << '\n';
    return 0;
}

