typedef long long ll;

int N;
ll cap[MAXN][MAXN];
bool visited[MAXN];
int parent[MAXN];

bool bfs(int s, int t) {
    memset(visited, 0, sizeof(visited));
    memset(parent, -1, sizeof(parent));
    int q[MAXN], front = 0, back = 0;
    q[back++] = s;
    visited[s] = true;
    while (front < back) {
        int u = q[front++];
        for (int v = 0; v <= t; v++) {
            if (!visited[v] && cap[u][v] > 0) {
                visited[v] = true;
                parent[v] = u;
                if (v == t) return true;
                q[back++] = v;
            }
        }
    }
    return false;
}

ll maxflow(int s, int t) {
    ll flow = 0;
    while (bfs(s, t)) {
        ll f = INF;
        for (int v = t; v != s; v = parent[v]) {
            int u = parent[v];
            if (cap[u][v] < f) f = cap[u][v];
        }
        for (int v = t; v != s; v = parent[v]) {
            int u = parent[v];
            cap[u][v] -= f;
            cap[v][u] += f;
        }
        flow += f;
    }
    return flow;
}

