typedef long long ll;

typedef struct {
    int to, rev;
    ll cap;
} Edge;

typedef struct {
    Edge *data;
    int sz, cap;
} Vec;

static void vec_push(Vec *v, Edge e) {
    if (v->sz == v->cap) {
        v->cap = v->cap ? v->cap * 2 : 4;
        v->data = (Edge*)realloc(v->data, sizeof(Edge) * v->cap);
    }
    v->data[v->sz++] = e;
}

static void add_edge(Vec *g, int u, int v, ll c) {
    Edge a = {v, g[v].sz, c};
    Edge b = {u, g[u].sz, 0};
    vec_push(&g[u], a);
    vec_push(&g[v], b);
}

static ll *level_arr, *it_arr;
static int *q_arr;

static int bfs(Vec *g, int n, int s, int t) {
    for (int i = 0; i < n; i++) level_arr[i] = -1;
    int qh = 0, qt = 0;
    level_arr[s] = 0;
    q_arr[qt++] = s;
    while (qh < qt) {
        int v = q_arr[qh++];
        for (int i = 0; i < g[v].sz; i++) {
            Edge *e = &g[v].data[i];
            if (e->cap > 0 && level_arr[e->to] < 0) {
                level_arr[e->to] = level_arr[v] + 1;
                q_arr[qt++] = e->to;
            }
        }
    }
    return level_arr[t] >= 0;
}

static ll minll(ll a, ll b) { return a < b ? a : b; }

static ll dfs(Vec *g, int v, int t, ll f) {
    if (v == t) return f;
    for (int *i = (int*)&it_arr[v]; *i < g[v].sz; (*i)++) {
        Edge *e = &g[v].data[*i];
        if (e->cap > 0 && level_arr[v] < level_arr[e->to]) {
            ll d = dfs(g, e->to, t, minll(f, e->cap));
            if (d > 0) {
                e->cap -= d;
                g[e->to].data[e->rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

static ll dinic(Vec *g, int n, int s, int t) {
    ll flow = 0, inf = (1LL << 60);
    while (bfs(g, n, s, t)) {
        for (int i = 0; i < n; i++) it_arr[i] = 0;
        while (1) {
            ll f = dfs(g, s, t, inf);
            if (!f) break;
            flow += f;
        }
    }
    return flow;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll **A = (ll**)malloc(sizeof(ll*) * N);
    for (int i = 0; i < N; i++) {
        A[i] = (ll*)malloc(sizeof(ll) * N);
        for (int j = 0; j < N; j++) scanf("%lld", &A[i][j]);
    }

    /*
      Key reduction:

      Let x_i be potentials. If every remaining edge u->v with weight w satisfies
      x_v <= x_u + w, then no negative cycle exists.
      Since initial edges i->i+1 have weight 0 and cannot be deleted:
          x_0 >= x_1 >= ... >= x_{N-1}
      For added edges:
        i < j, weight -1: need x_j <= x_i - 1 to keep it
        i > j, weight  1: need x_j <= x_i + 1, always true if x is nonincreasing
                           and adjacent differences are at most 1.
      With initial 0-edges and backward 1-edges, feasible x are exactly
          x_i = - (# of cuts among positions < i)
      where each adjacent gap is 0 or 1.
      Thus choose a partition of vertices into consecutive blocks.
      Forward edges inside same block must be deleted.
      Backward edges crossing at least two blocks must be deleted.

      Let cut between k and k+1 be chosen or not.
      Define side of cut. Cost contribution of a cut pattern equals:
        sum over i<j with no cut between i..j-1 of A[i][j]
      + sum over i>j with at least two cuts between j..i-1 of A[i][j]

      This can be solved as minimum s-t cut on interval nodes (l,r), l<r:
        If interval [l,r] has no cut inside, pay sum A[i][j] for (i,j)=(l,r) forward.
        If interval [l,r] has at most one cut inside, to keep backward edge r->l.
        Otherwise delete it, pay A[r][l].

      Standard closure graph:
        - Node F(l,r): profit/cost if interval has no cut.
        - Node B(l,r): profit/cost if interval has at most one cut.
        Dependencies:
          F(l,r) => F(l,r-1), F(l+1,r)
          B(l,r) => B(l,r-1), B(l+1,r)
          F(l,r) => B(l,r)
        Base intervals length 1 always true.
      But we need min deletion cost directly. Equivalent simpler formulation:

      Maximum saved cost from keeping edges:
        keep forward i<j iff no cut in [i, j-1]
        keep backward i>j iff at most one cut in [j, i-1]
      Build maximum weight closure with nodes:
        X[l][r]: interval [l,r] has no cut
        Y[l][r]: interval [l,r] has at most one cut
      Weights:
        +A[l][r+1]? easier with vertex indices intervals over edge positions.

      We'll index by vertex interval [i,j], i<j.
        X(i,j): no cut between i..j-1
        Y(i,j): at most one cut between i..j-1
      Saved if kept:
        forward i->j saves A[i][j] when X(i,j)
        backward j->i saves A[j][i] when Y(i,j)

      Closure relations:
        X(i,j) -> X(i,j-1), X(i+1,j)
        Y(i,j) -> Y(i,j-1), Y(i+1,j)
        X(i,j) -> Y(i,j)
      Base: X(i,i+1), Y(i,i+1) always true; Y(i,i+2) always true if desired follows recursively.

      Selecting closed set maximizing total weights.
      Force base nodes selected by infinite weight.
    */

    int M = N * N + 5;
    int totalNodes = 2; // s,t
    int **idX = (int**)malloc(sizeof(int*) * N);
    int **idY = (int**)malloc(sizeof(int*) * N);
    for (int i = 0; i < N; i++) {
        idX[i] = (int*)malloc(sizeof(int) * N);
        idY[i] = (int*)malloc(sizeof(int) * N);
        for (int j = 0; j < N; j++) idX[i][j] = idY[i][j] = -1;
    }

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            idX[i][j] = totalNodes++;
            idY[i][j] = totalNodes++;
        }
    }

    Vec *g = (Vec*)calloc(totalNodes, sizeof(Vec));
    level_arr = (ll*)malloc(sizeof(ll) * totalNodes);
    it_arr = (ll*)malloc(sizeof(ll) * totalNodes);
    q_arr = (int*)malloc(sizeof(int) * totalNodes);

    int S = 0, T = 1;
    ll INF = (1LL << 55);
    ll positive_sum = 0;

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            int x = idX[i][j];
            int y = idY[i][j];

            ll wx = A[i][j];
            ll wy = A[j][i];

            if (wx > 0) {
                add_edge(g, S, x, wx);
                positive_sum += wx;
            } else if (wx < 0) {
                add_edge(g, x, T, -wx);
            }

            if (wy > 0) {
                add_edge(g, S, y, wy);
                positive_sum += wy;
            } else if (wy < 0) {
                add_edge(g, y, T, -wy);
            }

            add_edge(g, x, y, INF); // X -> Y

            if (j == i + 1) {
                add_edge(g, S, x, INF);
                add_edge(g, S, y, INF);
                positive_sum += 2 * INF;
            } else {
                add_edge(g, x, idX[i][j - 1], INF);
                add_edge(g, x, idX[i + 1][j], INF);
                add_edge(g, y, idY[i][j - 1], INF);
                add_edge(g, y, idY[i + 1][j], INF);
            }
        }
    }

    ll max_closure = positive_sum - dinic(g, totalNodes, S, T);

    ll total_cost = 0;
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            if (i != j) total_cost += A[i][j];

    ll answer = total_cost - (max_closure - 2LL * (N - 1) * INF);

    printf("%lld\n", answer);
    return 0;
}

