public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();

        // minCut on DAG:
        // Keep all backward edges (j -> i, j>i), since they can never create a negative cycle.
        // For forward added edges (i -> j, i<j), a negative cycle exists iff there is a path
        // from j back to i using kept backward edges. Since backward reachability is transitive,
        // it is enough to ensure that for every i<j, we do NOT keep both:
        //   - forward edge i->j
        //   - direct backward edge j->i
        //
        // Thus for each pair i<j, at least one of these two edges must be deleted.
        // Cost:
        //   delete forward i->j : A[i][j]
        //   delete backward j->i: A[j][i]
        //
        // This is a minimum s-t cut on a bipartite graph:
        // left node L(i,j) = choose whether to keep forward edge
        // right node R(i,j) = choose whether to keep backward edge
        // edge L(i,j) -> R(i,j) with INF enforces not both kept.
        //
        // Equivalent simpler formulation:
        // Variables x[i][j] for i<j, where x=1 means keep forward i->j.
        // Variables must satisfy transitivity: if x[i][j]=1 and x[j][k]=1 then x[i][k]=1,
        // but in fact the min-cut construction below directly models closure by chain edges.
        //
        // Standard reduction:
        // Consider intervals (i,j), i<j.
        // If we keep backward edge j->i, then all larger intervals containing it matter.
        // More directly, define node (i,j), i<j, meaning "i can reach j" in the kept forward relation.
        // Choosing node (i,j) costs delete backward A[j][i] if false, delete forward A[i][j] if true.
        // Reachability must be transitive:
        // (i,j) and (j,k) => (i,k)
        //
        // This forms a closure problem solved by maximum weight closure / min-cut.
        //
        // Weight of selecting node (i,j):
        //   profit = A[j][i] - A[i][j]
        // base answer adds A[i][j] (delete all forward), then selecting means instead keep forward
        // and delete backward, changing cost by +A[j][i]-A[i][j].
        //
        // Need closure under transitivity:
        // if select (i,j) and select (j,k), must select (i,k).
        // This can be enforced by edges:
        // (i,j) + (j,k) -> (i,k), which is quadratic-hyperedge, not direct.
        //
        // Better equivalent closure:
        // Selecting (i,k) requires selecting at least one chain? Not enough.
        //
        // So use DP/min-cut on intervals:
        // Let f[i][j] be min cost for subarray [i..j] with partition point.
        // In fact problem is equivalent to finding a total preorder / partition into SCCs.
        // Because kept forward and backward edges between vertices imply reachability relation.
        //
        // Negative-cycle-free condition is equivalent to existence of potentials p[v] with:
        // p[v+1] <= p[v]
        // for forward added i<j kept: p[j] <= p[i]-1
        // for backward kept i>j: p[j] <= p[i]+1
        //
        // Since initial 0-edges force p nonincreasing, we can normalize p as integer levels and
        // vertices partition into contiguous blocks of equal p, decreasing by 0/1 steps.
        // Optimal can be represented by partition of vertices into contiguous groups:
        // - within same group, must delete all forward edges inside group? Actually if same potential,
        //   forward edge requires drop by 1, impossible, so any kept forward edge crosses to later lower group.
        // - backward edges from later to earlier always satisfy.
        //
        // To avoid negative cycles, it is sufficient and necessary to assign each vertex a level
        // nonincreasing along index. Keep forward i->j only if level[j] <= level[i]-1.
        // Since levels are integer and nonincreasing, this means every kept forward edge must cross
        // at least one strict drop. Thus levels define a partition into contiguous blocks; kept forward
        // edges are exactly those crossing blocks, forbidden inside a block.
        // Backward edges are always feasible regardless of levels, so never need deletion.
        //
        // Therefore only forward edges matter: to eliminate negative cycles, we need to delete all
        // forward added edges whose endpoints lie in the same block of some partition into contiguous blocks.
        // Minimize deleted cost => maximize kept cost across different blocks.
        //
        // Since backward edges need not be deleted at all, answer is min over partitions of sum of A[i][j]
        // for i<j within same block.
        //
        // DP: dp[r] = min cost for prefix [0..r-1]
        // dp[r] = min over l<r of dp[l] + cost of one block [l..r-1]
        // blockCost(l,r) = sum A[i][j] for l<=i<j<=r.
        //
        // Input gives full matrix A_{i,j}, i!=j. Diagonal may be absent or zero; read all N*N numbers.
        long[][] pref = new long[N + 1][N + 1];
        long[][] a = new long[N][N];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                a[i][j] = fs.nextLong();
                pref[i + 1][j + 1] = a[i][j] + pref[i][j + 1] + pref[i + 1][j] - pref[i][j];
            }
        }

        // blockCost(l, r): inclusive l..r, sum of a[i][j] for l<=i<j<=r
        long[][] block = new long[N][N];
        for (int l = 0; l < N; l++) {
            long sum = 0;
            for (int r = l; r < N; r++) {
                // add pairs (i, r) for l<=i<r
                for (int i = l; i < r; i++) sum += a[i][r];
                block[l][r] = sum;
            }
        }

        long[] dp = new long[N + 1];
        Arrays.fill(dp, Long.MAX_VALUE / 4);
        dp[0] = 0;
        for (int r = 1; r <= N; r++) {
            for (int l = 0; l < r; l++) {
                dp[r] = Math.min(dp[r], dp[l] + block[l][r - 1]);
            }
        }

        System.out.println(dp[N]);
    }
}
